GRANT SELECT ON public.email_opens TO service_role; GRANT SELECT ON public.email_clicks TO service_role; GRANT SELECT ON public.email_send_log TO service_role; DROP POLICY IF EXISTS "Service role can read email opens" ON public.email_opens; DROP POLICY IF EXISTS "Service role can read email clicks" ON public.email_clicks; DROP POLICY IF EXISTS "Service role can read email send log" ON public.email_send_log; CREATE POLICY "Service role can read email opens" ON public.email_opens FOR SELECT TO service_role USING (true); CREATE POLICY "Service role can read email clicks" ON public.email_clicks FOR SELECT TO service_role USING (true); CREATE POLICY "Service role can read email send log" ON public.email_send_log FOR SELECT TO service_role USING (true);